<template>
  <transition
    enter-from-class="translate-y-4 opacity-0"
    leave-to-class="translate-y-4 opacity-0"
    enter-active-class="transition-transform duration-300"
    leave-active-class="transition duration-300"
  >
    <Card v-if="isVisible" class="flex items-center gap-2 p-2 bg-green-50 border-green-300 w-full min-h-11 h-fit">
      <CircleCheck class="h-5 w-5 min-w-5 stroke-green-600 line-clamp-1" />
      <h3 class="text-green-600 font-medium">{{ text }}</h3>
    </Card>
  </transition>
</template>

<script setup lang="ts">
import { CircleCheck } from 'lucide-vue-next';

interface Props {
  text: string;
}

const props = defineProps<Props>();

const isVisible = defineModel<boolean>();

let timeoutId: NodeJS.Timeout | null = null;

watch(
  () => isVisible.value,
  (newVal, oldVal) => {
    if (newVal && newVal !== oldVal) {
      if (timeoutId !== null) {
        clearTimeout(timeoutId);
      }

      timeoutId = setTimeout(() => {
        isVisible.value = false;
      }, 4000);
    }
  }
);

onBeforeUnmount(() => {
  if (timeoutId !== null) {
    clearTimeout(timeoutId);
  }
});
</script>

<style scoped lang="scss"></style>
