      </div>
      <SuccessAlert v-model="showSuccessAlert" text="Sample saved successfully" />
      <AppLoader v-if="isLoading" variant="inline" title="Waiting to start" />
      <template v-if="recordState === 'inactive' && !recordedSample">
        <Button variant="default" class="w-fit h-10" @click="startRecord">New Sample</Button>
      </template>
      <template v-else-if="recordState === 'recording'">
        <div class="flex flex-col gap-2 items-center">
          <div class="flex gap-1 relative w-full overflow-hidden max-h-20 max-w-44 sm:max-w-64">
            <Wave class="wave min-w-full animate-scroll-wave" />
            <Wave class="wave min-w-full animate-scroll-wave" />
          </div>
          <div class="flex flex-col items-center text-accent-foreground gap-1">
            <p>{{ formatSecsToMins(recordTime) }}</p>
            <p>In progress...</p>
          </div>
        </div>
        <div class="flex items-center gap-4 flex-wrap">
          <Button
            variant="outline"
            class="flex gap-2 items-center border-muted h-10 min-w-40 max-sm:flex-auto"
            @click="stopRecord"
          >
            <CircleStop class="stroke-muted-foreground h-5 w-5" />
            <span>Stop</span>
          </Button>
          <Button variant="outline-destructive" class="h-10 min-w-40 max-sm:flex-auto" @click="cancelRecord"
            >Cancel
          </Button>
        </div>
      </template>
      <template v-else-if="recordedSample?.url">
        <AccountAudioPlayer :url="recordedSample.url">
          <AccountVoiceSampleDelete :disabled="isSaving" @delete="deleteRecord" />
          <Button
            variant="default"
            class="h-10"
            :disabled="!isSampleDurationEnough || isSaving"
            :loading="isSaving"
            @click="saveRecord"
          >
            Save Sample
          </Button>
        </AccountAudioPlayer>
      </template>
    </CardContent>
  </Card>
</template>

