import { Wave } from '~/assets/icons';

const {
  isLoading,
  isSaving,
  showSuccessAlert,
  recordedSample,
  recordState,
  recordTime,
  isSampleDurationEnough,
  startRecord,
  stopRecord,
  cancelRecord,
  deleteRecord,
  saveRecord,
