import { type AccountDetailsResponse, createVoiceSample, type CreateVoiceSampleResponse } from '~/client';

export const useCreateSample = defineMutation(() => {
  const refreshAccountAndRedirect = useRefreshAccountAndRedirect();

  const { mutateAsync: createSample } = useMutation({
    mutation: (data: { audio_data: string; audio_config: AudioConfig }): Promise<CreateVoiceSampleResponse> =>
      createVoiceSample({
        composable: '$fetch',
        body: data,
      }),
    onSuccess: async () => {
      showToastSuccess('Voice sample saved successfully');
      await refreshAccountAndRedirect();
    },
  });

  return {
    createSample,
  };
});
