import RecordRTC from 'recordrtc';
import fixWebmDuration from 'webm-duration-fix';

export const useSampleRecorder = () => {
  const { createSample } = useCreateSample();

  const recordedSample = ref<{ url: string; chunks: Blob[] } | null>(null);
  const mediaRecorder = ref<RecordRTC | null>(null);
  const isLoading = ref<boolean>(false);
  const isSaving = ref<boolean>(false);
  const showSuccessAlert = ref<boolean>(false);
  const recordTime = ref<number>(0);
  let timer: NodeJS.Timeout | null = null;

  let audioContext: AudioContext | null;
  let stream: MediaStream;

  const recordState = computed<RecordRTC.State>(() => {
    return mediaRecorder.value?.getState() ?? 'inactive';
  });

  const isSampleDurationEnough = computed<boolean>(() => {
    // todo replace 30 with value received from server
    return recordTime.value > 30;
  });

  async function startRecord() {
    if (mediaRecorder.value || isLoading.value) return;

    isLoading.value = true;
    recordedSample.value = { url: '', chunks: [] as Blob[] };
    stream = await navigator.mediaDevices.getUserMedia({ audio: true });

    mediaRecorder.value = new RecordRTC(stream, { type: 'audio' });
    mediaRecorder.value.startRecording();

    const sampleRate = stream.getAudioTracks()[0].getSettings().sampleRate || 48000;
    audioContext = new AudioContext({ sampleRate });

    await audioContext.audioWorklet.addModule('/audio-processor.js');
    const source = audioContext.createMediaStreamSource(stream);
    const audioProcessorNode = new AudioWorkletNode(audioContext, 'audio-processor');

    audioProcessorNode.port.onmessage = (event) => {
      if (event.data && recordedSample.value) {
        recordedSample.value.chunks!.push(event.data);
      }
    };

    source.connect(audioProcessorNode);
    audioProcessorNode.connect(audioContext.destination);

    recordTime.value = 0;
    //? may have problem with timer if user switch tabs
    timer = setInterval(() => {
      recordTime.value++;
    }, 1000);

    isLoading.value = false;
  }

  function cancelRecord() {
    mediaRecorder.value?.stopRecording(() => {
      mediaRecorder.value = null;
      recordedSample.value = null;
      stopAudioContext();
      resetTimer();
    });
  }

  function stopRecord() {
    if (!isSampleDurationEnough.value) showToastError('Verification sample is too short');

    mediaRecorder.value?.stopRecording(async () => {
      if (recordedSample.value) {
        let blob = mediaRecorder.value!.getBlob();
        if (blob.type.includes('webm')) {
          blob = await fixWebmDuration(blob);
        }
        recordedSample.value.url = blob ? URL.createObjectURL(blob) : '';
      }
      mediaRecorder.value = null;
      resetTimer();
    });
    stopAudioContext();
  }

  function stopAudioContext() {
    audioContext?.close();
    audioContext = null;
    stopStreamTracks(stream);
  }

  function resetTimer() {
    if (timer) {
      clearInterval(timer);
      timer = null;
    }
  }

  function deleteRecord() {
    recordedSample.value = null;
  }

  async function saveRecord() {
    if (!recordedSample.value || isSaving.value) return;

    try {
      isSaving.value = true;
      const combinedChunks = new Blob(recordedSample.value.chunks);
      const arrayBuffer = await combinedChunks.arrayBuffer();
      await createSample({
        audio_data: arrayBufferToBase64(arrayBuffer),
        audio_config: createAudioConfig(stream),
      });
    } catch (error: any) {
      showToastError(error);
    } finally {
      isSaving.value = false;
    }
  }

  return {
    isLoading,
    isSaving,
    showSuccessAlert,
    recordedSample,
    recordState,
    recordTime,
    isSampleDurationEnough,
    startRecord,
    cancelRecord,
    stopRecord,
    saveRecord,
    deleteRecord,
  };
};
